const config = {
  "previewFeatures": [],
  "clientVersion": "7.10.0",
  "engineVersion": "0edf323efd1d98336f3f0a68684b56f689b900d3",
  "activeProvider": "postgresql",
  "inlineSchema": "// BetterERP - Production multi-branch ERP + POS database schema\n// Database: PostgreSQL 16\n\ngenerator client {\n  provider = \"prisma-client-js\"\n}\n\ndatasource db {\n  provider = \"postgresql\"\n}\n\n// ============================================================\n// ORGANIZATION STRUCTURE\n// ============================================================\n\nenum EntityStatus {\n  ACTIVE\n  INACTIVE\n  ARCHIVED\n}\n\nmodel Company {\n  id                 String   @id @default(cuid())\n  name               String\n  legalName          String?\n  registrationNumber String?\n  vatNumber          String?\n  address            String?\n  city               String?\n  country            String   @default(\"Zimbabwe\")\n  phone              String?\n  email              String?\n  website            String?\n  currency           String   @default(\"USD\")\n  baseCurrency       String   @default(\"USD\")\n  fiscalYearStart    DateTime\n  isHq               Boolean  @default(true)\n  logoUrl            String?\n  settings           Json?\n  createdAt          DateTime @default(now())\n  updatedAt          DateTime @updatedAt\n\n  branches   Branch[]\n  addresses  CompanyAddress[]\n  accounts   Account[]\n  currencies Currency[]\n  users      User[]\n}\n\nmodel CompanyAddress {\n  id        String   @id @default(cuid())\n  companyId String\n  company   Company  @relation(fields: [companyId], references: [id])\n  type      String // STREET, POSTAL, PHYSICAL\n  line1     String\n  line2     String?\n  city      String\n  province  String?\n  country   String   @default(\"Zimbabwe\")\n  isDefault Boolean  @default(false)\n  createdAt DateTime @default(now())\n\n  @@index([companyId])\n}\n\nmodel Branch {\n  id                      String       @id @default(cuid())\n  companyId               String\n  company                 Company      @relation(fields: [companyId], references: [id], onDelete: Cascade)\n  code                    String\n  name                    String\n  type                    String       @default(\"BRANCH\") // HQ, BRANCH, WAREHOUSE_ONLY\n  address                 String?\n  city                    String?\n  phone                   String?\n  email                   String?\n  managerUserId           String?\n  managerName             String?\n  status                  EntityStatus @default(ACTIVE)\n  currency                String?      @default(\"USD\")\n  defaultWarehouseId      String?\n  taxConfiguration        Json?\n  accountingConfiguration Json?\n  posConfiguration        Json?\n  createdAt               DateTime     @default(now())\n  updatedAt               DateTime     @updatedAt\n\n  warehouses       Warehouse[]\n  users            User[]\n  employees        Employee[]\n  accounts         Account[]\n  cashAccounts     Account[]         @relation(\"BranchCashAccounts\")\n  bankAccounts     BankAccount[]\n  customers        Customer[]\n  suppliers        Supplier[]\n  products         ProductBranch[] // branch-specific product config\n  sales            Sale[]\n  purchaseOrders   PurchaseOrder[]\n  supplierInvoices SupplierInvoice[]\n  transfersOut     StockTransfer[]   @relation(\"TransferSourceBranch\")\n  transfersIn      StockTransfer[]   @relation(\"TransferDestinationBranch\")\n\n  @@unique([companyId, code])\n  @@index([companyId])\n}\n\nmodel Warehouse {\n  id        String       @id @default(cuid())\n  branchId  String\n  branch    Branch       @relation(fields: [branchId], references: [id], onDelete: Cascade)\n  code      String\n  name      String\n  address   String?\n  isDefault Boolean      @default(false)\n  status    EntityStatus @default(ACTIVE)\n  createdAt DateTime     @default(now())\n  updatedAt DateTime     @updatedAt\n\n  locations     WarehouseLocation[]\n  stockBalances StockBalance[]\n  stockCounts   StockCount[]\n\n  @@unique([branchId, code])\n  @@index([branchId])\n}\n\nmodel WarehouseLocation {\n  id          String       @id @default(cuid())\n  warehouseId String\n  warehouse   Warehouse    @relation(fields: [warehouseId], references: [id], onDelete: Cascade)\n  code        String\n  name        String\n  description String?\n  status      EntityStatus @default(ACTIVE)\n  createdAt   DateTime     @default(now())\n\n  stockBalances StockBalance[]\n\n  @@unique([warehouseId, code])\n  @@index([warehouseId])\n}\n\nmodel Department {\n  id          String       @id @default(cuid())\n  companyId   String\n  code        String\n  name        String\n  description String?\n  managerId   String?\n  status      EntityStatus @default(ACTIVE)\n  createdAt   DateTime     @default(now())\n  updatedAt   DateTime     @updatedAt\n\n  employees     Employee[]\n  costCentres   CostCentre[]\n  profitCentres ProfitCentre[]\n\n  @@unique([companyId, code])\n  @@index([companyId])\n}\n\nmodel CostCentre {\n  id           String       @id @default(cuid())\n  companyId    String\n  departmentId String?\n  department   Department?  @relation(fields: [departmentId], references: [id])\n  code         String\n  name         String\n  description  String?\n  status       EntityStatus @default(ACTIVE)\n  createdAt    DateTime     @default(now())\n\n  @@unique([companyId, code])\n  @@index([companyId])\n}\n\nmodel ProfitCentre {\n  id           String       @id @default(cuid())\n  companyId    String\n  departmentId String?\n  department   Department?  @relation(fields: [departmentId], references: [id])\n  code         String\n  name         String\n  description  String?\n  status       EntityStatus @default(ACTIVE)\n  createdAt    DateTime     @default(now())\n\n  @@unique([companyId, code])\n  @@index([companyId])\n}\n\n// ============================================================\n// AUTHENTICATION & AUTHORIZATION\n// ============================================================\n\nmodel User {\n  id                 String    @id @default(cuid())\n  companyId          String\n  company            Company   @relation(fields: [companyId], references: [id], onDelete: Cascade)\n  branchId           String?\n  branch             Branch?   @relation(fields: [branchId], references: [id])\n  username           String    @unique\n  email              String?   @unique\n  fullName           String\n  phone              String?\n  passwordHash       String\n  isActive           Boolean   @default(true)\n  mustChangePassword Boolean   @default(true)\n  lastLoginAt        DateTime?\n  failedLoginCount   Int       @default(0)\n  lockedUntil        DateTime?\n  passwordChangedAt  DateTime?\n  canViewAllBranches Boolean   @default(false)\n  createdAt          DateTime  @default(now())\n  updatedAt          DateTime  @updatedAt\n\n  roles                   UserRole[]\n  loginHistory            LoginHistory[]\n  auditLogs               AuditLog[]\n  employee                Employee?\n  notifications           UserNotification[]\n  sessions                Session[]\n  passwordResetTokens     PasswordResetToken[]\n  stockAdjustmentsCreated StockAdjustment[]    @relation(\"AdjustmentCreator\")\n  salesAsCashier          Sale[]               @relation(\"SaleCashier\")\n  shiftsAsCashier         POSShift[]           @relation(\"ShiftCashier\")\n  stockMovements          StockMovement[]      @relation(\"StockMovementUser\")\n  expensesPaid            Expense[]            @relation(\"ExpensePaidBy\")\n\n  @@index([companyId])\n  @@index([branchId])\n}\n\nmodel Role {\n  id          String   @id @default(cuid())\n  companyId   String\n  name        String\n  description String?\n  isSystem    Boolean  @default(false)\n  isDefault   Boolean  @default(false)\n  createdAt   DateTime @default(now())\n  updatedAt   DateTime @updatedAt\n\n  permissions    RolePermission[]\n  users          UserRole[]\n  approvalLevels ApprovalLevel[]\n\n  @@unique([companyId, name])\n  @@index([companyId])\n}\n\nmodel Permission {\n  id          String   @id @default(cuid())\n  code        String   @unique\n  module      String\n  resource    String\n  action      String // view, create, edit, delete, approve, post, cancel, reverse, export, print\n  description String?\n  createdAt   DateTime @default(now())\n\n  roles RolePermission[]\n}\n\nmodel RolePermission {\n  roleId       String\n  role         Role       @relation(fields: [roleId], references: [id], onDelete: Cascade)\n  permissionId String\n  permission   Permission @relation(fields: [permissionId], references: [id], onDelete: Cascade)\n  createdAt    DateTime   @default(now())\n\n  @@id([roleId, permissionId])\n  @@index([permissionId])\n}\n\nmodel UserRole {\n  userId    String\n  user      User     @relation(fields: [userId], references: [id], onDelete: Cascade)\n  roleId    String\n  role      Role     @relation(fields: [roleId], references: [id], onDelete: Cascade)\n  branchId  String?\n  createdAt DateTime @default(now())\n\n  @@id([userId, roleId])\n  @@index([roleId])\n  @@index([branchId])\n}\n\nmodel LoginHistory {\n  id        String    @id @default(cuid())\n  userId    String\n  user      User      @relation(fields: [userId], references: [id], onDelete: Cascade)\n  branchId  String?\n  ip        String?\n  userAgent String?\n  success   Boolean\n  reason    String?\n  loginAt   DateTime  @default(now())\n  logoutAt  DateTime?\n\n  @@index([userId])\n  @@index([loginAt])\n}\n\nmodel Session {\n  id        String    @id @default(cuid())\n  userId    String\n  user      User      @relation(fields: [userId], references: [id], onDelete: Cascade)\n  tokenHash String    @unique\n  ip        String?\n  userAgent String?\n  expiresAt DateTime\n  createdAt DateTime  @default(now())\n  revokedAt DateTime?\n  isRevoked Boolean   @default(false)\n\n  @@index([userId])\n}\n\nmodel PasswordResetToken {\n  id        String    @id @default(cuid())\n  userId    String\n  user      User      @relation(fields: [userId], references: [id], onDelete: Cascade)\n  tokenHash String    @unique\n  expiresAt DateTime\n  usedAt    DateTime?\n  createdAt DateTime  @default(now())\n\n  @@index([userId])\n}\n\n// ============================================================\n// PRODUCT MASTER\n// ============================================================\n\nmodel Category {\n  id          String       @id @default(cuid())\n  companyId   String\n  parentId    String?\n  parent      Category?    @relation(\"CategoryTree\", fields: [parentId], references: [id])\n  children    Category[]   @relation(\"CategoryTree\")\n  code        String\n  name        String\n  description String?\n  status      EntityStatus @default(ACTIVE)\n  createdAt   DateTime     @default(now())\n  updatedAt   DateTime     @updatedAt\n\n  products Product[]\n\n  @@unique([companyId, code])\n  @@index([companyId])\n}\n\nmodel Brand {\n  id        String       @id @default(cuid())\n  companyId String\n  name      String\n  code      String?\n  status    EntityStatus @default(ACTIVE)\n  createdAt DateTime     @default(now())\n\n  products Product[]\n\n  @@unique([companyId, name])\n  @@index([companyId])\n}\n\nmodel UnitOfMeasure {\n  id        String   @id @default(cuid())\n  companyId String\n  code      String\n  name      String\n  isBase    Boolean  @default(false)\n  createdAt DateTime @default(now())\n\n  products Product[]\n\n  @@unique([companyId, code])\n  @@index([companyId])\n}\n\nenum ProductType {\n  STOCK\n  SERVICE\n  NON_STOCK\n  ASSET\n}\n\nenum CostingMethod {\n  WEIGHTED_AVERAGE\n  FIFO\n  STANDARD\n}\n\nmodel Product {\n  id                  String         @id @default(cuid())\n  companyId           String\n  sku                 String\n  barcode             String?\n  name                String\n  description         String?\n  categoryId          String?\n  category            Category?      @relation(fields: [categoryId], references: [id])\n  subcategoryId       String?\n  brandId             String?\n  brand               Brand?         @relation(fields: [brandId], references: [id])\n  unitOfMeasureId     String?\n  unitOfMeasure       UnitOfMeasure? @relation(fields: [unitOfMeasureId], references: [id])\n  purchaseUnit        String?\n  stockUnit           String?\n  salesUnit           String?\n  packSize            Decimal?       @db.Decimal(12, 2)\n  alternateUnits      Json?\n  type                ProductType    @default(STOCK)\n  costingMethod       CostingMethod  @default(WEIGHTED_AVERAGE)\n  costPrice           Decimal?       @default(0) @db.Decimal(18, 4)\n  averageCost         Decimal?       @default(0) @db.Decimal(18, 4)\n  lastPurchasePrice   Decimal?       @db.Decimal(18, 4)\n  sellingPrice        Decimal?       @db.Decimal(18, 4)\n  wholesalePrice      Decimal?       @db.Decimal(18, 4)\n  retailPrice         Decimal?       @db.Decimal(18, 4)\n  specialPrice        Decimal?       @db.Decimal(18, 4)\n  taxCategoryId       String?\n  taxRateId           String?\n  taxRate             TaxRate?       @relation(fields: [taxRateId], references: [id])\n  reorderLevel        Decimal?       @default(0) @db.Decimal(18, 4)\n  reorderQuantity     Decimal?       @default(0) @db.Decimal(18, 4)\n  minimumStock        Decimal?       @default(0) @db.Decimal(18, 4)\n  maximumStock        Decimal?       @db.Decimal(18, 4)\n  preferredSupplierId String?\n  preferredSupplier   Supplier?      @relation(\"PreferredSupplier\", fields: [preferredSupplierId], references: [id])\n  imageUrl            String?\n  imagePath           String?\n  serialRequired      Boolean        @default(false)\n  batchRequired       Boolean        @default(false)\n  expiryRequired      Boolean        @default(false)\n  weight              Decimal?       @db.Decimal(12, 4)\n  length              Decimal?       @db.Decimal(12, 4)\n  width               Decimal?       @db.Decimal(12, 4)\n  height              Decimal?       @db.Decimal(12, 4)\n  allowNegative       Boolean        @default(false)\n  status              EntityStatus   @default(ACTIVE)\n  createdAt           DateTime       @default(now())\n  updatedAt           DateTime       @updatedAt\n  createdById         String?\n\n  suppliers            ProductSupplier[]\n  aliases              ProductAlias[]\n  priceHistory         ProductPriceHistory[]\n  branchConfigs        ProductBranch[]\n  stockBalances        StockBalance[]\n  saleLines            SaleLine[]\n  purchaseLines        PurchaseOrderLine[]\n  movements            StockMovement[]\n  goodsReceiptLines    GoodsReceiptLine[]\n  stockAdjustmentLines StockAdjustmentLine[]\n  stockCountLines      StockCountLine[]\n  stockTransferLines   StockTransferLine[]\n\n  @@unique([companyId, sku])\n  @@unique([companyId, barcode])\n  @@index([companyId, name])\n  @@index([companyId, categoryId])\n  @@index([companyId, brandId])\n}\n\nmodel ProductAlias {\n  id        String   @id @default(cuid())\n  productId String\n  product   Product  @relation(fields: [productId], references: [id], onDelete: Cascade)\n  alias     String\n  createdAt DateTime @default(now())\n\n  @@index([productId])\n  @@index([alias])\n}\n\nmodel ProductSupplier {\n  id           String   @id @default(cuid())\n  productId    String\n  product      Product  @relation(fields: [productId], references: [id], onDelete: Cascade)\n  supplierId   String\n  supplier     Supplier @relation(fields: [supplierId], references: [id], onDelete: Cascade)\n  supplierCode String?\n  costPrice    Decimal? @db.Decimal(18, 4)\n  leadTimeDays Int?\n  isPreferred  Boolean  @default(false)\n  createdAt    DateTime @default(now())\n\n  @@unique([productId, supplierId])\n  @@index([supplierId])\n}\n\nmodel ProductBranch {\n  id             String       @id @default(cuid())\n  productId      String\n  product        Product      @relation(fields: [productId], references: [id], onDelete: Cascade)\n  branchId       String\n  branch         Branch       @relation(fields: [branchId], references: [id], onDelete: Cascade)\n  sellingPrice   Decimal?     @db.Decimal(18, 4)\n  wholesalePrice Decimal?     @db.Decimal(18, 4)\n  retailPrice    Decimal?     @db.Decimal(18, 4)\n  specialPrice   Decimal?     @db.Decimal(18, 4)\n  reorderLevel   Decimal?     @db.Decimal(18, 4)\n  status         EntityStatus @default(ACTIVE)\n  createdAt      DateTime     @default(now())\n  updatedAt      DateTime     @updatedAt\n\n  @@unique([productId, branchId])\n  @@index([branchId])\n}\n\nmodel ProductPriceHistory {\n  id          String   @id @default(cuid())\n  productId   String\n  product     Product  @relation(fields: [productId], references: [id], onDelete: Cascade)\n  branchId    String?\n  field       String\n  oldValue    Decimal? @db.Decimal(18, 4)\n  newValue    Decimal? @db.Decimal(18, 4)\n  changedById String?\n  changedAt   DateTime @default(now())\n\n  @@index([productId])\n  @@index([changedAt])\n}\n\n// ============================================================\n// INVENTORY\n// ============================================================\n\nenum StockMovementType {\n  PURCHASE_RECEIPT\n  SALES\n  SALES_RETURN\n  PURCHASE_RETURN\n  BRANCH_TRANSFER_OUT\n  BRANCH_TRANSFER_IN\n  BRANCH_TRANSFER_RECEIVE\n  STOCK_ADJUSTMENT\n  STOCK_COUNT\n  DAMAGE\n  WRITE_OFF\n  OPENING_STOCK\n  INTERNAL_CONSUMPTION\n  TRANSFER_IN_TRANSIT\n}\n\nmodel StockMovement {\n  id          String            @id @default(cuid())\n  companyId   String\n  branchId    String\n  warehouseId String?\n  reference   String\n  type        StockMovementType\n  productId   String\n  product     Product           @relation(fields: [productId], references: [id])\n  quantity    Decimal           @db.Decimal(18, 4)\n  beforeQty   Decimal           @db.Decimal(18, 4)\n  afterQty    Decimal           @db.Decimal(18, 4)\n  unitCost    Decimal?          @db.Decimal(18, 4)\n  totalCost   Decimal?          @db.Decimal(18, 4)\n  sourceRef   String?\n  sourceType  String?\n  sourceId    String?\n  userId      String?\n  user        User?             @relation(\"StockMovementUser\", fields: [userId], references: [id])\n  note        String?\n  createdAt   DateTime          @default(now())\n\n  @@index([companyId, productId])\n  @@index([branchId])\n  @@index([type])\n  @@index([sourceId])\n  @@index([createdAt])\n}\n\nmodel StockBalance {\n  id          String             @id @default(cuid())\n  productId   String\n  product     Product            @relation(fields: [productId], references: [id], onDelete: Cascade)\n  warehouseId String\n  warehouse   Warehouse          @relation(fields: [warehouseId], references: [id], onDelete: Cascade)\n  locationId  String?\n  location    WarehouseLocation? @relation(fields: [locationId], references: [id])\n  onHand      Decimal            @default(0) @db.Decimal(18, 4)\n  reserved    Decimal            @default(0) @db.Decimal(18, 4)\n  available   Decimal            @default(0) @db.Decimal(18, 4)\n  damaged     Decimal            @default(0) @db.Decimal(18, 4)\n  inTransit   Decimal            @default(0) @db.Decimal(18, 4)\n  ordered     Decimal            @default(0) @db.Decimal(18, 4)\n  averageCost Decimal            @default(0) @db.Decimal(18, 4)\n  value       Decimal            @default(0) @db.Decimal(18, 4)\n  updatedAt   DateTime           @updatedAt\n\n  @@unique([productId, warehouseId, locationId])\n  @@index([warehouseId])\n  @@index([productId])\n}\n\nmodel StockAdjustment {\n  id           String    @id @default(cuid())\n  companyId    String\n  branchId     String\n  warehouseId  String?\n  reference    String\n  type         String // STOCK_ADJUSTMENT, DAMAGE, WRITE_OFF, INTERNAL_CONSUMPTION, STOCK_COUNT\n  note         String?\n  status       String    @default(\"DRAFT\") // DRAFT, PENDING, APPROVED, POSTED, CANCELLED\n  postedAt     DateTime?\n  postedById   String?\n  createdById  String?\n  createdBy    User?     @relation(\"AdjustmentCreator\", fields: [createdById], references: [id])\n  approvedById String?\n  createdAt    DateTime  @default(now())\n  updatedAt    DateTime  @updatedAt\n\n  lines StockAdjustmentLine[]\n\n  @@index([companyId, branchId])\n}\n\nmodel StockAdjustmentLine {\n  id             String          @id @default(cuid())\n  adjustmentId   String\n  adjustment     StockAdjustment @relation(fields: [adjustmentId], references: [id], onDelete: Cascade)\n  productId      String\n  product        Product         @relation(fields: [productId], references: [id])\n  locationId     String?\n  quantityChange Decimal         @db.Decimal(18, 4)\n  newOnHand      Decimal?        @db.Decimal(18, 4)\n  reason         String?\n  unitCost       Decimal?        @db.Decimal(18, 4)\n\n  @@index([adjustmentId])\n}\n\nmodel StockCount {\n  id               String    @id @default(cuid())\n  companyId        String\n  branchId         String\n  warehouseId      String\n  warehouse        Warehouse @relation(fields: [warehouseId], references: [id])\n  reference        String\n  status           String    @default(\"DRAFT\") // DRAFT, IN_PROGRESS, COUNTED, ADJUSTED, POSTED, CANCELLED\n  countedById      String?\n  countDate        DateTime  @default(now())\n  varianceAccounts Json?\n  note             String?\n  createdAt        DateTime  @default(now())\n  updatedAt        DateTime  @updatedAt\n\n  lines StockCountLine[]\n\n  @@index([companyId, branchId])\n}\n\nmodel StockCountLine {\n  id         String     @id @default(cuid())\n  countId    String\n  count      StockCount @relation(fields: [countId], references: [id], onDelete: Cascade)\n  productId  String\n  product    Product    @relation(fields: [productId], references: [id])\n  locationId String?\n  systemQty  Decimal    @db.Decimal(18, 4)\n  countedQty Decimal    @db.Decimal(18, 4)\n  variance   Decimal    @db.Decimal(18, 4)\n  unitCost   Decimal?   @db.Decimal(18, 4)\n\n  @@index([countId])\n}\n\n// ============================================================\n// SUPPLIERS & CUSTOMERS\n// ============================================================\n\nmodel Supplier {\n  id            String       @id @default(cuid())\n  companyId     String\n  branchId      String?\n  branch        Branch?      @relation(fields: [branchId], references: [id])\n  code          String?\n  name          String\n  taxNumber     String?\n  contactPerson String?\n  phone         String?\n  email         String?\n  address       String?\n  city          String?\n  province      String?\n  country       String       @default(\"Zimbabwe\")\n  currency      String       @default(\"USD\")\n  creditLimit   Decimal?     @default(0) @db.Decimal(18, 4)\n  paymentTerms  String?\n  bankAccount   String?\n  status        EntityStatus @default(ACTIVE)\n  notes         String?\n  createdAt     DateTime     @default(now())\n  updatedAt     DateTime     @updatedAt\n\n  products          ProductSupplier[]\n  preferredProducts Product[]         @relation(\"PreferredSupplier\")\n  purchaseOrders    PurchaseOrder[]\n  contacts          SupplierContact[]\n  invoices          SupplierInvoice[]\n  payments          SupplierPayment[]\n\n  @@unique([companyId, code])\n  @@index([companyId, name])\n  @@index([branchId])\n}\n\nmodel SupplierContact {\n  id         String   @id @default(cuid())\n  supplierId String\n  supplier   Supplier @relation(fields: [supplierId], references: [id], onDelete: Cascade)\n  name       String\n  title      String?\n  phone      String?\n  email      String?\n  isPrimary  Boolean  @default(false)\n  createdAt  DateTime @default(now())\n\n  @@index([supplierId])\n}\n\nmodel Customer {\n  id                 String         @id @default(cuid())\n  companyId          String\n  branchId           String?\n  branch             Branch?        @relation(fields: [branchId], references: [id])\n  code               String?\n  name               String\n  customerType       String         @default(\"RETAIL\") // RETAIL, WHOLESALE, CONTRACT, CREDIT\n  groupId            String?\n  group              CustomerGroup? @relation(fields: [groupId], references: [id])\n  taxNumber          String?\n  contactPerson      String?\n  phone              String?\n  email              String?\n  address            String?\n  city               String?\n  province           String?\n  country            String         @default(\"Zimbabwe\")\n  currency           String         @default(\"USD\")\n  creditLimit        Decimal?       @default(0) @db.Decimal(18, 4)\n  creditApproved     Boolean        @default(false)\n  creditApprovedById String?\n  paymentTerms       String?\n  priceTier          String? // RETAIL, WHOLESALE, SPECIAL\n  status             EntityStatus   @default(ACTIVE)\n  notes              String?\n  createdAt          DateTime       @default(now())\n  updatedAt          DateTime       @updatedAt\n\n  sales    Sale[]\n  receipts CustomerReceipt[]\n\n  @@unique([companyId, code])\n  @@index([companyId, name])\n  @@index([branchId])\n}\n\nmodel CustomerGroup {\n  id        String       @id @default(cuid())\n  companyId String\n  name      String\n  discount  Decimal?     @default(0) @db.Decimal(5, 2)\n  priceTier String?\n  status    EntityStatus @default(ACTIVE)\n  createdAt DateTime     @default(now())\n\n  customers Customer[]\n\n  @@unique([companyId, name])\n}\n\n// ============================================================\n// PROCUREMENT\n// ============================================================\n\nenum PurchaseStatus {\n  DRAFT\n  PENDING_APPROVAL\n  APPROVED\n  PARTIAL_RECEIVED\n  RECEIVED\n  CANCELLED\n  COMPLETED\n}\n\nmodel PurchaseRequest {\n  id            String   @id @default(cuid())\n  companyId     String\n  branchId      String\n  reference     String\n  requestedById String?\n  status        String   @default(\"DRAFT\") // DRAFT, PENDING, APPROVED, REJECTED\n  note          String?\n  createdAt     DateTime @default(now())\n  updatedAt     DateTime @updatedAt\n\n  @@index([companyId, branchId])\n}\n\nmodel PurchaseOrder {\n  id           String         @id @default(cuid())\n  companyId    String\n  branchId     String\n  branch       Branch         @relation(fields: [branchId], references: [id])\n  supplierId   String\n  supplier     Supplier       @relation(fields: [supplierId], references: [id])\n  reference    String\n  status       PurchaseStatus @default(DRAFT)\n  orderDate    DateTime       @default(now())\n  expectedDate DateTime?\n  currency     String         @default(\"USD\")\n  exchangeRate Decimal        @default(1) @db.Decimal(18, 6)\n  subtotal     Decimal        @default(0) @db.Decimal(18, 4)\n  discount     Decimal        @default(0) @db.Decimal(18, 4)\n  taxAmount    Decimal        @default(0) @db.Decimal(18, 4)\n  total        Decimal        @default(0) @db.Decimal(18, 4)\n  notes        String?\n  approvedById String?\n  approvedAt   DateTime?\n  createdById  String?\n  createdAt    DateTime       @default(now())\n  updatedAt    DateTime       @updatedAt\n\n  lines    PurchaseOrderLine[]\n  receipts GoodsReceipt[]\n  invoices SupplierInvoice[]\n\n  @@index([companyId, branchId])\n  @@index([supplierId])\n  @@index([status])\n}\n\nmodel PurchaseOrderLine {\n  id              String        @id @default(cuid())\n  purchaseOrderId String\n  purchaseOrder   PurchaseOrder @relation(fields: [purchaseOrderId], references: [id], onDelete: Cascade)\n  productId       String?\n  product         Product?      @relation(fields: [productId], references: [id])\n  description     String?\n  quantity        Decimal       @db.Decimal(18, 4)\n  receivedQty     Decimal       @default(0) @db.Decimal(18, 4)\n  backorderQty    Decimal       @default(0) @db.Decimal(18, 4)\n  unitCost        Decimal       @db.Decimal(18, 4)\n  taxRate         Decimal?      @default(0) @db.Decimal(5, 2)\n  taxAmount       Decimal       @default(0) @db.Decimal(18, 4)\n  lineTotal       Decimal       @default(0) @db.Decimal(18, 4)\n\n  @@index([purchaseOrderId])\n}\n\nmodel GoodsReceipt {\n  id              String         @id @default(cuid())\n  companyId       String\n  branchId        String\n  warehouseId     String?\n  purchaseOrderId String?\n  purchaseOrder   PurchaseOrder? @relation(fields: [purchaseOrderId], references: [id])\n  supplierId      String\n  reference       String // GRN number\n  receiptDate     DateTime       @default(now())\n  status          String         @default(\"POSTED\") // DRAFT, POSTED, CANCELLED\n  receivedById    String?\n  totalQty        Decimal        @default(0) @db.Decimal(18, 4)\n  note            String?\n  createdAt       DateTime       @default(now())\n  updatedAt       DateTime       @updatedAt\n\n  lines GoodsReceiptLine[]\n\n  @@index([companyId, branchId])\n  @@index([purchaseOrderId])\n}\n\nmodel GoodsReceiptLine {\n  id                  String       @id @default(cuid())\n  goodsReceiptId      String\n  goodsReceipt        GoodsReceipt @relation(fields: [goodsReceiptId], references: [id], onDelete: Cascade)\n  purchaseOrderLineId String?\n  productId           String?\n  product             Product?     @relation(fields: [productId], references: [id])\n  quantity            Decimal      @db.Decimal(18, 4)\n  unitCost            Decimal      @db.Decimal(18, 4)\n  taxAmount           Decimal      @default(0) @db.Decimal(18, 4)\n  lineTotal           Decimal      @default(0) @db.Decimal(18, 4)\n  locationId          String?\n\n  @@index([goodsReceiptId])\n}\n\nmodel SupplierInvoice {\n  id              String         @id @default(cuid())\n  companyId       String\n  branchId        String\n  branch          Branch         @relation(fields: [branchId], references: [id])\n  supplierId      String\n  supplier        Supplier       @relation(fields: [supplierId], references: [id])\n  purchaseOrderId String?\n  purchaseOrder   PurchaseOrder? @relation(fields: [purchaseOrderId], references: [id])\n  reference       String // supplier invoice number\n  docReference    String // internal reference\n  invoiceDate     DateTime       @default(now())\n  dueDate         DateTime?\n  currency        String         @default(\"USD\")\n  exchangeRate    Decimal        @default(1) @db.Decimal(18, 6)\n  subtotal        Decimal        @default(0) @db.Decimal(18, 4)\n  discount        Decimal        @default(0) @db.Decimal(18, 4)\n  taxAmount       Decimal        @default(0) @db.Decimal(18, 4)\n  total           Decimal        @default(0) @db.Decimal(18, 4)\n  amountPaid      Decimal        @default(0) @db.Decimal(18, 4)\n  status          String         @default(\"OPEN\") // OPEN, PARTIAL, PAID, OVERDUE, CANCELLED\n  posted          Boolean        @default(false)\n  postedAt        DateTime?\n  createdAt       DateTime       @default(now())\n  updatedAt       DateTime       @updatedAt\n\n  lines    SupplierInvoiceLine[]\n  payments SupplierPayment[]\n\n  @@index([companyId, branchId])\n  @@index([supplierId])\n  @@index([status])\n}\n\nmodel SupplierInvoiceLine {\n  id                  String          @id @default(cuid())\n  invoiceId           String\n  invoice             SupplierInvoice @relation(fields: [invoiceId], references: [id], onDelete: Cascade)\n  purchaseOrderLineId String?\n  productId           String?\n  description         String?\n  quantity            Decimal         @db.Decimal(18, 4)\n  unitCost            Decimal         @db.Decimal(18, 4)\n  taxAmount           Decimal         @default(0) @db.Decimal(18, 4)\n  lineTotal           Decimal         @default(0) @db.Decimal(18, 4)\n\n  @@index([invoiceId])\n}\n\nmodel PurchaseReturn {\n  id         String   @id @default(cuid())\n  companyId  String\n  branchId   String\n  supplierId String\n  reference  String\n  returnDate DateTime @default(now())\n  reason     String?\n  status     String   @default(\"POSTED\")\n  total      Decimal  @default(0) @db.Decimal(18, 4)\n  createdAt  DateTime @default(now())\n\n  lines PurchaseReturnLine[]\n\n  @@index([companyId, branchId])\n}\n\nmodel PurchaseReturnLine {\n  id               String         @id @default(cuid())\n  purchaseReturnId String\n  purchaseReturn   PurchaseReturn @relation(fields: [purchaseReturnId], references: [id], onDelete: Cascade)\n  productId        String?\n  quantity         Decimal        @db.Decimal(18, 4)\n  unitCost         Decimal        @db.Decimal(18, 4)\n  taxAmount        Decimal        @default(0) @db.Decimal(18, 4)\n  lineTotal        Decimal        @default(0) @db.Decimal(18, 4)\n\n  @@index([purchaseReturnId])\n}\n\nmodel SupplierPayment {\n  id            String           @id @default(cuid())\n  companyId     String\n  branchId      String\n  supplierId    String\n  supplier      Supplier         @relation(fields: [supplierId], references: [id])\n  invoiceId     String?\n  invoice       SupplierInvoice? @relation(fields: [invoiceId], references: [id])\n  reference     String\n  paymentDate   DateTime         @default(now())\n  amount        Decimal          @db.Decimal(18, 4)\n  paymentMethod String\n  bankAccountId String?\n  bankAccount   BankAccount?     @relation(fields: [bankAccountId], references: [id])\n  currency      String           @default(\"USD\")\n  exchangeRate  Decimal          @default(1) @db.Decimal(18, 6)\n  notes         String?\n  posted        Boolean          @default(false)\n  postedAt      DateTime?\n  createdAt     DateTime         @default(now())\n\n  @@index([companyId, branchId])\n  @@index([supplierId])\n}\n\n// ============================================================\n// SALES & POS\n// ============================================================\n\nenum SaleType {\n  POS\n  INVOICE\n  WHOLESALE\n  RETAIL\n  QUOTATION\n}\n\nenum SaleStatus {\n  DRAFT\n  HELD\n  COMPLETED\n  RETURNED\n  CANCELLED\n  VOID\n  PARTIAL_RETURN\n}\n\nmodel Quotation {\n  id         String    @id @default(cuid())\n  companyId  String\n  branchId   String\n  customerId String?\n  reference  String\n  validUntil DateTime?\n  status     String    @default(\"DRAFT\") // DRAFT, SENT, ACCEPTED, CONVERTED, EXPIRED, CANCELLED\n  subtotal   Decimal   @default(0) @db.Decimal(18, 4)\n  discount   Decimal   @default(0) @db.Decimal(18, 4)\n  taxAmount  Decimal   @default(0) @db.Decimal(18, 4)\n  total      Decimal   @default(0) @db.Decimal(18, 4)\n  createdAt  DateTime  @default(now())\n  createdBy  String?\n\n  lines QuotationLine[]\n\n  @@index([companyId, branchId])\n}\n\nmodel QuotationLine {\n  id          String    @id @default(cuid())\n  quotationId String\n  quotation   Quotation @relation(fields: [quotationId], references: [id], onDelete: Cascade)\n  productId   String?\n  quantity    Decimal   @db.Decimal(18, 4)\n  unitPrice   Decimal   @db.Decimal(18, 4)\n  discount    Decimal   @default(0) @db.Decimal(18, 4)\n  taxAmount   Decimal   @default(0) @db.Decimal(18, 4)\n  lineTotal   Decimal   @default(0) @db.Decimal(18, 4)\n\n  @@index([quotationId])\n}\n\nmodel SalesOrder {\n  id         String   @id @default(cuid())\n  companyId  String\n  branchId   String\n  customerId String?\n  reference  String\n  orderDate  DateTime @default(now())\n  status     String   @default(\"DRAFT\") // DRAFT, APPROVED, FULFILLED, PARTIAL, CANCELLED\n  subtotal   Decimal  @default(0) @db.Decimal(18, 4)\n  discount   Decimal  @default(0) @db.Decimal(18, 4)\n  taxAmount  Decimal  @default(0) @db.Decimal(18, 4)\n  total      Decimal  @default(0) @db.Decimal(18, 4)\n  createdAt  DateTime @default(now())\n  createdBy  String?\n\n  lines SalesOrderLine[]\n\n  @@index([companyId, branchId])\n}\n\nmodel SalesOrderLine {\n  id           String     @id @default(cuid())\n  salesOrderId String\n  salesOrder   SalesOrder @relation(fields: [salesOrderId], references: [id], onDelete: Cascade)\n  productId    String?\n  quantity     Decimal    @db.Decimal(18, 4)\n  unitPrice    Decimal    @db.Decimal(18, 4)\n  discount     Decimal    @default(0) @db.Decimal(18, 4)\n  taxAmount    Decimal    @default(0) @db.Decimal(18, 4)\n  lineTotal    Decimal    @default(0) @db.Decimal(18, 4)\n\n  @@index([salesOrderId])\n}\n\nmodel Sale {\n  id                   String     @id @default(cuid())\n  companyId            String\n  branchId             String\n  branch               Branch     @relation(fields: [branchId], references: [id])\n  warehouseId          String?\n  customerId           String?\n  customer             Customer?  @relation(fields: [customerId], references: [id])\n  reference            String\n  type                 SaleType   @default(POS)\n  status               SaleStatus @default(COMPLETED)\n  saleDate             DateTime   @default(now())\n  cashierId            String\n  cashier              User       @relation(\"SaleCashier\", fields: [cashierId], references: [id])\n  shiftId              String?\n  shift                POSShift?  @relation(fields: [shiftId], references: [id])\n  subtotal             Decimal    @default(0) @db.Decimal(18, 4)\n  discount             Decimal    @default(0) @db.Decimal(18, 4)\n  taxAmount            Decimal    @default(0) @db.Decimal(18, 4)\n  total                Decimal    @default(0) @db.Decimal(18, 4)\n  amountPaid           Decimal    @default(0) @db.Decimal(18, 4)\n  changeDue            Decimal    @default(0) @db.Decimal(18, 4)\n  currency             String     @default(\"USD\")\n  exchangeRate         Decimal    @default(1) @db.Decimal(18, 6)\n  paymentMethod        String?\n  isCredit             Boolean    @default(false)\n  creditDueDate        DateTime?\n  discountApprovedById String?\n  discountApprovedAt   DateTime?\n  voidedById           String?\n  voidedAt             DateTime?\n  voidReason           String?\n  heldId               String?\n  notes                String?\n  postedAt             DateTime?\n  createdAt            DateTime   @default(now())\n  updatedAt            DateTime   @updatedAt\n\n  lines    SaleLine[]\n  payments SalePayment[]\n  returns  SaleReturn[]\n\n  @@index([companyId, branchId])\n  @@index([customerId])\n  @@index([saleDate])\n  @@index([status])\n}\n\nmodel SaleLine {\n  id          String   @id @default(cuid())\n  saleId      String\n  sale        Sale     @relation(fields: [saleId], references: [id], onDelete: Cascade)\n  productId   String?\n  product     Product? @relation(fields: [productId], references: [id])\n  description String?\n  quantity    Decimal  @db.Decimal(18, 4)\n  unitPrice   Decimal  @db.Decimal(18, 4)\n  costPrice   Decimal? @db.Decimal(18, 4)\n  discount    Decimal  @default(0) @db.Decimal(18, 4)\n  taxRate     Decimal? @default(0) @db.Decimal(5, 2)\n  taxAmount   Decimal  @default(0) @db.Decimal(18, 4)\n  lineTotal   Decimal  @default(0) @db.Decimal(18, 4)\n\n  @@index([saleId])\n}\n\nmodel SalePayment {\n  id             String   @id @default(cuid())\n  saleId         String\n  sale           Sale     @relation(fields: [saleId], references: [id], onDelete: Cascade)\n  amount         Decimal  @db.Decimal(18, 4)\n  currencyAmount Decimal? @db.Decimal(18, 4)\n  currency       String   @default(\"USD\")\n  exchangeRate   Decimal  @default(1) @db.Decimal(18, 6)\n  paymentMethod  String\n  reference      String?\n  bankAccountId  String?\n  createdAt      DateTime @default(now())\n  createdBy      String?\n\n  @@index([saleId])\n}\n\nmodel SaleReturn {\n  id           String   @id @default(cuid())\n  companyId    String\n  branchId     String\n  saleId       String?\n  sale         Sale?    @relation(fields: [saleId], references: [id])\n  customerId   String?\n  reference    String\n  returnDate   DateTime @default(now())\n  reason       String?\n  refundMethod String?\n  refundAmount Decimal  @default(0) @db.Decimal(18, 4)\n  status       String   @default(\"POSTED\")\n  createdById  String?\n  createdAt    DateTime @default(now())\n\n  lines SaleReturnLine[]\n\n  @@index([companyId, branchId])\n  @@index([saleId])\n}\n\nmodel SaleReturnLine {\n  id           String     @id @default(cuid())\n  saleReturnId String\n  saleReturn   SaleReturn @relation(fields: [saleReturnId], references: [id], onDelete: Cascade)\n  productId    String?\n  quantity     Decimal    @db.Decimal(18, 4)\n  unitPrice    Decimal    @db.Decimal(18, 4)\n  taxAmount    Decimal    @default(0) @db.Decimal(18, 4)\n  lineTotal    Decimal    @default(0) @db.Decimal(18, 4)\n\n  @@index([saleReturnId])\n}\n\nmodel CustomerReceipt {\n  id            String    @id @default(cuid())\n  companyId     String\n  branchId      String\n  customerId    String\n  customer      Customer  @relation(fields: [customerId], references: [id])\n  reference     String\n  receiptDate   DateTime  @default(now())\n  amount        Decimal   @db.Decimal(18, 4)\n  paymentMethod String\n  bankAccountId String?\n  invoiceId     String?\n  notes         String?\n  posted        Boolean   @default(false)\n  postedAt      DateTime?\n  createdAt     DateTime  @default(now())\n\n  @@index([companyId, branchId])\n  @@index([customerId])\n}\n\n// ============================================================\n// POS SHIFT & CASH\n// ============================================================\n\nmodel POSShift {\n  id               String    @id @default(cuid())\n  companyId        String\n  branchId         String\n  cashierId        String\n  cashier          User      @relation(\"ShiftCashier\", fields: [cashierId], references: [id])\n  terminal         String?\n  status           String    @default(\"OPEN\") // OPEN, CLOSED, CANCELLED\n  openingFloat     Decimal   @default(0) @db.Decimal(18, 4)\n  openedAt         DateTime  @default(now())\n  closedAt         DateTime?\n  expectedCash     Decimal   @default(0) @db.Decimal(18, 4)\n  countedCash      Decimal?  @db.Decimal(18, 4)\n  variance         Decimal?  @db.Decimal(18, 4)\n  varianceNotes    String?\n  varianceApproved Boolean   @default(false)\n  closedById       String?\n  createdAt        DateTime  @default(now())\n\n  sales  Sale[]\n  events POSShiftEvent[]\n\n  @@index([companyId, branchId])\n  @@index([cashierId])\n  @@index([status])\n}\n\nenum POSShiftEventType {\n  OPEN\n  FLOAT\n  CASH_DROP\n  CASH_UP\n  DECLARATION\n  EXPENSE\n  REFUND\n  CLOSE\n}\n\nmodel POSShiftEvent {\n  id          String            @id @default(cuid())\n  shiftId     String\n  shift       POSShift          @relation(fields: [shiftId], references: [id], onDelete: Cascade)\n  type        POSShiftEventType\n  amount      Decimal           @db.Decimal(18, 4)\n  method      String?\n  note        String?\n  createdById String?\n  createdAt   DateTime          @default(now())\n\n  @@index([shiftId])\n}\n\n// ============================================================\n// STOCK TRANSFERS\n// ============================================================\n\nenum TransferStatus {\n  REQUESTED\n  PENDING_APPROVAL\n  APPROVED\n  DISPATCHED\n  IN_TRANSIT\n  PARTIAL_RECEIVED\n  RECEIVED\n  CANCELLED\n}\n\nmodel StockTransfer {\n  id                     String         @id @default(cuid())\n  companyId              String\n  reference              String\n  sourceBranchId         String\n  sourceWarehouseId      String?\n  destinationBranchId    String\n  destinationWarehouseId String?\n  status                 TransferStatus @default(REQUESTED)\n  requestedById          String?\n  approvedById           String?\n  dispatchedById         String?\n  receivedById           String?\n  requestedAt            DateTime       @default(now())\n  approvedAt             DateTime?\n  dispatchedAt           DateTime?\n  receivedAt             DateTime?\n  expectedAt             DateTime?\n  note                   String?\n  createdAt              DateTime       @default(now())\n  updatedAt              DateTime       @updatedAt\n\n  sourceBranch      Branch              @relation(\"TransferSourceBranch\", fields: [sourceBranchId], references: [id])\n  destinationBranch Branch              @relation(\"TransferDestinationBranch\", fields: [destinationBranchId], references: [id])\n  lines             StockTransferLine[]\n\n  @@index([companyId, sourceBranchId])\n  @@index([destinationBranchId])\n  @@index([status])\n}\n\nmodel StockTransferLine {\n  id            String        @id @default(cuid())\n  transferId    String\n  transfer      StockTransfer @relation(fields: [transferId], references: [id], onDelete: Cascade)\n  productId     String?\n  product       Product?      @relation(fields: [productId], references: [id])\n  requestedQty  Decimal       @db.Decimal(18, 4)\n  dispatchedQty Decimal       @default(0) @db.Decimal(18, 4)\n  receivedQty   Decimal       @default(0) @db.Decimal(18, 4)\n  damagedQty    Decimal       @default(0) @db.Decimal(18, 4)\n  unitCost      Decimal?      @db.Decimal(18, 4)\n\n  @@index([transferId])\n}\n\n// ============================================================\n// ACCOUNTING\n// ============================================================\n\nenum AccountType {\n  ASSET\n  LIABILITY\n  EQUITY\n  REVENUE\n  EXPENSE\n  CONTRA_ASSET\n  CONTRA_REVENUE\n}\n\nenum AccountNormalBalance {\n  DEBIT\n  CREDIT\n}\n\nmodel Account {\n  id             String               @id @default(cuid())\n  companyId      String\n  company        Company              @relation(fields: [companyId], references: [id], onDelete: Cascade)\n  branchId       String?\n  branch         Branch?              @relation(fields: [branchId], references: [id])\n  code           String\n  name           String\n  type           AccountType\n  category       String? // e.g. CASH, BANK, RECEIVABLE, PAYABLE, etc.\n  normalBalance  AccountNormalBalance\n  currency       String?              @default(\"USD\")\n  parentId       String?\n  parent         Account?             @relation(\"AccountTree\", fields: [parentId], references: [id])\n  children       Account[]            @relation(\"AccountTree\")\n  isControl      Boolean              @default(false)\n  isActive       Boolean              @default(true)\n  description    String?\n  openingBalance Decimal              @default(0) @db.Decimal(18, 4)\n  createdAt      DateTime             @default(now())\n  updatedAt      DateTime             @updatedAt\n\n  journalLines           JournalLine[]\n  bankAccounts           BankAccount[]\n  cashAccountForBranchId String?\n  cashAccountForBranch   Branch?           @relation(\"BranchCashAccounts\", fields: [cashAccountForBranchId], references: [id])\n  expenseCategories      ExpenseCategory[]\n\n  @@unique([companyId, branchId, code])\n  @@index([companyId])\n  @@index([branchId])\n}\n\nmodel JournalEntry {\n  id           String    @id @default(cuid())\n  companyId    String\n  branchId     String?\n  reference    String\n  description  String?\n  entryType    String // SALE, PURCHASE, PAYMENT, RECEIPT, EXPENSE, TRANSFER, ADJUSTMENT, OPENING, PAYROLL, DEPRECIATION\n  sourceType   String?\n  sourceId     String?\n  currency     String    @default(\"USD\")\n  exchangeRate Decimal   @default(1) @db.Decimal(18, 6)\n  entryDate    DateTime  @default(now())\n  posted       Boolean   @default(false)\n  postedAt     DateTime?\n  reversed     Boolean   @default(false)\n  reversedById String?\n  reversedAt   DateTime?\n  reversalOfId String?\n  createdById  String?\n  createdAt    DateTime  @default(now())\n  updatedAt    DateTime  @updatedAt\n\n  lines     JournalLine[]\n  relation  JournalEntry?  @relation(\"Reversal\", fields: [reversalOfId], references: [id])\n  reversals JournalEntry[] @relation(\"Reversal\")\n\n  @@index([companyId, branchId])\n  @@index([sourceType, sourceId])\n  @@index([entryDate])\n  @@index([entryType])\n}\n\nmodel JournalLine {\n  id             String       @id @default(cuid())\n  journalEntryId String\n  journalEntry   JournalEntry @relation(fields: [journalEntryId], references: [id], onDelete: Cascade)\n  accountId      String\n  account        Account      @relation(fields: [accountId], references: [id])\n  branchId       String?\n  departmentId   String?\n  costCentreId   String?\n  profitCentreId String?\n  debit          Decimal      @default(0) @db.Decimal(18, 4)\n  credit         Decimal      @default(0) @db.Decimal(18, 4)\n  description    String?\n  createdAt      DateTime     @default(now())\n\n  @@index([journalEntryId])\n  @@index([accountId])\n  @@index([branchId])\n}\n\nmodel BankAccount {\n  id             String       @id @default(cuid())\n  companyId      String\n  branchId       String?\n  branch         Branch?      @relation(fields: [branchId], references: [id])\n  accountId      String?\n  account        Account?     @relation(fields: [accountId], references: [id])\n  accountName    String\n  bankName       String\n  accountNumber  String\n  branchCode     String?\n  swiftCode      String?\n  currency       String       @default(\"USD\")\n  openingBalance Decimal      @default(0) @db.Decimal(18, 4)\n  status         EntityStatus @default(ACTIVE)\n  isDefault      Boolean      @default(false)\n  createdAt      DateTime     @default(now())\n  updatedAt      DateTime     @updatedAt\n\n  transactions     BankTransaction[]\n  reconciliations  BankReconciliation[]\n  supplierPayments SupplierPayment[]\n\n  @@index([companyId])\n  @@index([branchId])\n}\n\nmodel BankTransaction {\n  id               String      @id @default(cuid())\n  bankAccountId    String\n  bankAccount      BankAccount @relation(fields: [bankAccountId], references: [id], onDelete: Cascade)\n  transactionDate  DateTime    @default(now())\n  description      String\n  reference        String?\n  withdrawal       Decimal     @default(0) @db.Decimal(18, 4)\n  deposit          Decimal     @default(0) @db.Decimal(18, 4)\n  balance          Decimal     @db.Decimal(18, 4)\n  reconciled       Boolean     @default(false)\n  reconciliationId String?\n  sourceType       String? // DEPOSIT, WITHDRAWAL, TRANSFER, PAYMENT, RECEIPT\n  sourceId         String?\n  createdAt        DateTime    @default(now())\n\n  @@index([bankAccountId])\n  @@index([reconciled])\n}\n\nmodel BankReconciliation {\n  id               String      @id @default(cuid())\n  bankAccountId    String\n  bankAccount      BankAccount @relation(fields: [bankAccountId], references: [id], onDelete: Cascade)\n  statementDate    DateTime    @default(now())\n  statementBalance Decimal     @db.Decimal(18, 4)\n  bookBalance      Decimal     @db.Decimal(18, 4)\n  difference       Decimal     @db.Decimal(18, 4)\n  status           String      @default(\"IN_PROGRESS\") // IN_PROGRESS, COMPLETED\n  reconciledById   String?\n  completedAt      DateTime?\n  createdAt        DateTime    @default(now())\n\n  @@index([bankAccountId])\n}\n\nmodel FinancialPeriod {\n  id         String    @id @default(cuid())\n  companyId  String\n  name       String\n  startDate  DateTime\n  endDate    DateTime\n  status     String    @default(\"OPEN\") // OPEN, CLOSED, LOCKED\n  closedById String?\n  closedAt   DateTime?\n  createdAt  DateTime  @default(now())\n\n  @@unique([companyId, name])\n  @@index([companyId])\n}\n\n// ============================================================\n// TAX & CURRENCY\n// ============================================================\n\nmodel TaxRate {\n  id            String    @id @default(cuid())\n  companyId     String\n  name          String\n  rate          Decimal   @db.Decimal(5, 2) // percentage\n  type          String    @default(\"VAT\") // VAT, INPUT, OUTPUT, ZERO_RATED, EXEMPT\n  isCompound    Boolean   @default(false)\n  isActive      Boolean   @default(true)\n  effectiveFrom DateTime  @default(now())\n  effectiveTo   DateTime?\n  createdAt     DateTime  @default(now())\n  updatedAt     DateTime  @updatedAt\n\n  products Product[]\n\n  @@index([companyId])\n}\n\nmodel Currency {\n  id        String   @id @default(cuid())\n  companyId String\n  company   Company  @relation(fields: [companyId], references: [id], onDelete: Cascade)\n  code      String\n  name      String\n  symbol    String\n  isBase    Boolean  @default(false)\n  isActive  Boolean  @default(true)\n  createdAt DateTime @default(now())\n\n  exchangeRates ExchangeRate[]\n\n  @@unique([companyId, code])\n  @@index([companyId])\n}\n\nmodel ExchangeRate {\n  id            String   @id @default(cuid())\n  currencyId    String\n  currency      Currency @relation(fields: [currencyId], references: [id], onDelete: Cascade)\n  rateToBase    Decimal  @db.Decimal(18, 6)\n  effectiveDate DateTime @default(now())\n  createdAt     DateTime @default(now())\n\n  @@index([currencyId, effectiveDate])\n}\n\n// ============================================================\n// EXPENSES\n// ============================================================\n\nmodel Expense {\n  id              String           @id @default(cuid())\n  companyId       String\n  branchId        String\n  categoryId      String?\n  expenseCategory ExpenseCategory? @relation(fields: [categoryId], references: [id])\n  reference       String\n  expenseDate     DateTime         @default(now())\n  description     String\n  amount          Decimal          @db.Decimal(18, 4)\n  taxAmount       Decimal          @default(0) @db.Decimal(18, 4)\n  currency        String           @default(\"USD\")\n  exchangeRate    Decimal          @default(1) @db.Decimal(18, 6)\n  supplierId      String?\n  paymentMethod   String?\n  bankAccountId   String?\n  paidById        String?\n  paidBy          User?            @relation(\"ExpensePaidBy\", fields: [paidById], references: [id])\n  status          String           @default(\"PENDING\") // PENDING, APPROVED, PAID, REJECTED\n  approvedById    String?\n  approvedAt      DateTime?\n  receiptPath     String?\n  posted          Boolean          @default(false)\n  postedAt        DateTime?\n  createdById     String?\n  createdAt       DateTime         @default(now())\n  updatedAt       DateTime         @updatedAt\n\n  @@index([companyId, branchId])\n  @@index([expenseDate])\n}\n\nmodel ExpenseCategory {\n  id        String       @id @default(cuid())\n  companyId String\n  name      String\n  accountId String?\n  account   Account?     @relation(fields: [accountId], references: [id])\n  status    EntityStatus @default(ACTIVE)\n  createdAt DateTime     @default(now())\n\n  expenses Expense[]\n\n  @@unique([companyId, name])\n}\n\nmodel PettyCash {\n  id          String       @id @default(cuid())\n  companyId   String\n  branchId    String\n  name        String\n  balance     Decimal      @default(0) @db.Decimal(18, 4)\n  topUpAmount Decimal?     @db.Decimal(18, 4)\n  status      EntityStatus @default(ACTIVE)\n  createdAt   DateTime     @default(now())\n\n  @@index([companyId, branchId])\n}\n\n// ============================================================\n// HR & PAYROLL\n// ============================================================\n\nenum EmploymentStatus {\n  ACTIVE\n  ON_LEAVE\n  TERMINATED\n  SUSPENDED\n  RESIGNED\n  RETIRED\n}\n\nmodel Employee {\n  id                String           @id @default(cuid())\n  companyId         String\n  branchId          String?\n  branch            Branch?          @relation(fields: [branchId], references: [id])\n  employeeNumber    String           @unique\n  userId            String?          @unique\n  user              User?            @relation(fields: [userId], references: [id])\n  firstName         String\n  lastName          String\n  middleName        String?\n  dateOfBirth       DateTime?\n  gender            String?\n  nationalId        String?\n  phone             String?\n  email             String?\n  address           String?\n  city              String?\n  departmentId      String?\n  department        Department?      @relation(fields: [departmentId], references: [id])\n  positionId        String?\n  position          Position?        @relation(fields: [positionId], references: [id])\n  managerId         String?\n  employmentType    String           @default(\"FULL_TIME\")\n  employmentStatus  EmploymentStatus @default(ACTIVE)\n  hireDate          DateTime         @default(now())\n  terminationDate   DateTime?\n  salaryType        String           @default(\"MONTHLY\") // MONTHLY, HOURLY, COMMISSION\n  basicSalary       Decimal?         @default(0) @db.Decimal(18, 4)\n  hourlyRate        Decimal?         @default(0) @db.Decimal(18, 4)\n  bankName          String?\n  bankAccountNumber String?\n  bankBranch        String?\n  nssaNumber        String?\n  taxNumber         String?\n  isSalaried        Boolean          @default(true)\n  createdAt         DateTime         @default(now())\n  updatedAt         DateTime         @updatedAt\n\n  allowances    EmployeeAllowance[]\n  deductions    EmployeeDeduction[]\n  leaveRequests LeaveRequest[]\n  attendance    Attendance[]\n  documents     EmployeeDocument[]\n  loans         EmployeeLoan[]\n  payrollLines  PayrollLine[]\n  assets        Asset[]\n\n  @@index([companyId])\n  @@index([branchId])\n  @@index([departmentId])\n}\n\nmodel Position {\n  id           String   @id @default(cuid())\n  companyId    String\n  name         String\n  description  String?\n  departmentId String?\n  createdAt    DateTime @default(now())\n\n  employees Employee[]\n\n  @@unique([companyId, name])\n}\n\nmodel EmployeeAllowance {\n  id         String   @id @default(cuid())\n  employeeId String\n  employee   Employee @relation(fields: [employeeId], references: [id], onDelete: Cascade)\n  name       String\n  type       String // FIXED, PERCENTAGE\n  amount     Decimal  @db.Decimal(18, 4)\n  percentage Decimal? @db.Decimal(5, 2)\n  isTaxable  Boolean  @default(true)\n  createdAt  DateTime @default(now())\n\n  @@index([employeeId])\n}\n\nmodel EmployeeDeduction {\n  id          String   @id @default(cuid())\n  employeeId  String\n  employee    Employee @relation(fields: [employeeId], references: [id], onDelete: Cascade)\n  name        String\n  type        String // FIXED, PERCENTAGE\n  amount      Decimal  @db.Decimal(18, 4)\n  percentage  Decimal? @db.Decimal(5, 2)\n  isStatutory Boolean  @default(false)\n  createdAt   DateTime @default(now())\n\n  @@index([employeeId])\n}\n\nmodel EmployeeLoan {\n  id                 String    @id @default(cuid())\n  employeeId         String\n  employee           Employee  @relation(fields: [employeeId], references: [id], onDelete: Cascade)\n  amount             Decimal   @db.Decimal(18, 4)\n  monthlyDeduction   Decimal   @db.Decimal(18, 4)\n  outstandingBalance Decimal   @default(0) @db.Decimal(18, 4)\n  startDate          DateTime  @default(now())\n  endDate            DateTime?\n  status             String    @default(\"ACTIVE\") // ACTIVE, COMPLETED, DEFAULTED\n  createdAt          DateTime  @default(now())\n\n  @@index([employeeId])\n}\n\nenum LeaveType {\n  ANNUAL\n  SICK\n  MATERNITY\n  PATERNITY\n  UNPAID\n  COMPASSIONATE\n  STUDY\n  OTHER\n}\n\nenum LeaveStatus {\n  PENDING\n  APPROVED\n  REJECTED\n  CANCELLED\n  TAKEN\n}\n\nmodel LeaveRequest {\n  id           String      @id @default(cuid())\n  companyId    String\n  branchId     String?\n  employeeId   String\n  employee     Employee    @relation(fields: [employeeId], references: [id], onDelete: Cascade)\n  leaveType    LeaveType\n  startDate    DateTime\n  endDate      DateTime\n  days         Int\n  reason       String?\n  status       LeaveStatus @default(PENDING)\n  approvedById String?\n  approvedAt   DateTime?\n  createdAt    DateTime    @default(now())\n\n  @@index([employeeId])\n  @@index([status])\n}\n\nmodel Attendance {\n  id          String    @id @default(cuid())\n  companyId   String\n  branchId    String?\n  employeeId  String\n  employee    Employee  @relation(fields: [employeeId], references: [id], onDelete: Cascade)\n  date        DateTime\n  clockIn     DateTime?\n  clockOut    DateTime?\n  hoursWorked Decimal?  @db.Decimal(6, 2)\n  status      String    @default(\"PRESENT\") // PRESENT, ABSENT, LATE, LEAVE\n  note        String?\n  createdAt   DateTime  @default(now())\n\n  @@unique([employeeId, date])\n  @@index([employeeId])\n  @@index([date])\n}\n\nmodel EmployeeDocument {\n  id           String   @id @default(cuid())\n  employeeId   String\n  employee     Employee @relation(fields: [employeeId], references: [id], onDelete: Cascade)\n  name         String\n  type         String\n  filePath     String\n  uploadedAt   DateTime @default(now())\n  uploadedById String?\n\n  @@index([employeeId])\n}\n\nmodel Payroll {\n  id              String    @id @default(cuid())\n  companyId       String\n  branchId        String?\n  reference       String?\n  periodName      String\n  periodStart     DateTime\n  periodEnd       DateTime\n  payDate         DateTime  @default(now())\n  status          String    @default(\"DRAFT\") // DRAFT, PENDING_APPROVAL, APPROVED, POSTED, CANCELLED\n  totalGross      Decimal   @default(0) @db.Decimal(18, 4)\n  totalDeductions Decimal   @default(0) @db.Decimal(18, 4)\n  totalNet        Decimal   @default(0) @db.Decimal(18, 4)\n  totalTax        Decimal   @default(0) @db.Decimal(18, 4)\n  approvedById    String?\n  approvedAt      DateTime?\n  posted          Boolean   @default(false)\n  postedAt        DateTime?\n  currency        String    @default(\"USD\")\n  exchangeRate    Decimal   @default(1) @db.Decimal(18, 6)\n  createdAt       DateTime  @default(now())\n  updatedAt       DateTime  @updatedAt\n\n  lines PayrollLine[]\n\n  @@index([companyId, branchId])\n  @@index([status])\n}\n\nmodel PayrollLine {\n  id                  String   @id @default(cuid())\n  payrollId           String\n  payroll             Payroll  @relation(fields: [payrollId], references: [id], onDelete: Cascade)\n  employeeId          String\n  employee            Employee @relation(fields: [employeeId], references: [id])\n  basicSalary         Decimal  @default(0) @db.Decimal(18, 4)\n  allowances          Decimal  @default(0) @db.Decimal(18, 4)\n  bonuses             Decimal  @default(0) @db.Decimal(18, 4)\n  overtime            Decimal  @default(0) @db.Decimal(18, 4)\n  grossPay            Decimal  @default(0) @db.Decimal(18, 4)\n  statutoryDeductions Decimal  @default(0) @db.Decimal(18, 4) // PAYE, NSSA\n  otherDeductions     Decimal  @default(0) @db.Decimal(18, 4)\n  loanDeductions      Decimal  @default(0) @db.Decimal(18, 4)\n  totalDeductions     Decimal  @default(0) @db.Decimal(18, 4)\n  netPay              Decimal  @default(0) @db.Decimal(18, 4)\n  payeAmount          Decimal  @default(0) @db.Decimal(18, 4)\n  nssaAmount          Decimal  @default(0) @db.Decimal(18, 4)\n  pensionAmount       Decimal  @default(0) @db.Decimal(18, 4)\n  currency            String   @default(\"USD\")\n  exchangeRate        Decimal  @default(1) @db.Decimal(18, 6)\n\n  @@index([payrollId])\n  @@index([employeeId])\n}\n\nmodel PayrollSetting {\n  id            String    @id @default(cuid())\n  companyId     String\n  name          String\n  value         Decimal   @db.Decimal(18, 4)\n  type          String // PAYE_BRACKET, NSSA_RATE, NSSA_CEILING, AID_LEVY, PENSION\n  effectiveFrom DateTime  @default(now())\n  effectiveTo   DateTime?\n  createdAt     DateTime  @default(now())\n\n  @@index([companyId, type])\n}\n\n// ============================================================\n// FIXED ASSETS\n// ============================================================\n\nmodel AssetCategory {\n  id                 String   @id @default(cuid())\n  companyId          String\n  name               String\n  depreciationRate   Decimal  @default(0) @db.Decimal(5, 2)\n  depreciationMethod String   @default(\"STRAIGHT_LINE\")\n  expenseAccountId   String?\n  assetAccountId     String?\n  createdAt          DateTime @default(now())\n\n  assets Asset[]\n\n  @@unique([companyId, name])\n}\n\nmodel Asset {\n  id                      String         @id @default(cuid())\n  companyId               String\n  branchId                String?\n  categoryId              String?\n  category                AssetCategory? @relation(fields: [categoryId], references: [id])\n  assetNumber             String         @unique\n  name                    String\n  description             String?\n  serialNumber            String?\n  purchaseDate            DateTime?\n  purchaseCost            Decimal        @db.Decimal(18, 4)\n  salvageValue            Decimal        @default(0) @db.Decimal(18, 4)\n  usefulLifeYears         Int?\n  depreciationRate        Decimal        @default(0) @db.Decimal(5, 2)\n  accumulatedDepreciation Decimal        @default(0) @db.Decimal(18, 4)\n  bookValue               Decimal        @db.Decimal(18, 4)\n  status                  String         @default(\"ACTIVE\") // ACTIVE, DISPOSED, IN_REPAIR, RETIRED\n  location                String?\n  assignedTo              String?\n  assignedEmployeeId      String?\n  assignedEmployee        Employee?      @relation(fields: [assignedEmployeeId], references: [id])\n  supplierId              String?\n  notes                   String?\n  createdAt               DateTime       @default(now())\n  updatedAt               DateTime       @updatedAt\n\n  deprecations AssetDepreciation[]\n\n  @@index([companyId])\n  @@index([branchId])\n  @@index([categoryId])\n}\n\nmodel AssetDepreciation {\n  id        String   @id @default(cuid())\n  assetId   String\n  asset     Asset    @relation(fields: [assetId], references: [id], onDelete: Cascade)\n  period    String\n  amount    Decimal  @db.Decimal(18, 4)\n  bookedAt  DateTime @default(now())\n  journalId String?\n\n  @@index([assetId])\n}\n\n// ============================================================\n// SYSTEM: AUDIT, NOTIFICATIONS, NUMBERING, FILES, SETTINGS\n// ============================================================\n\nenum AuditAction {\n  CREATE\n  UPDATE\n  DELETE\n  APPROVE\n  REJECT\n  POST\n  CANCEL\n  REVERSE\n  LOGIN\n  LOGOUT\n  LOGIN_FAILED\n  PRICE_CHANGE\n  STOCK_ADJUSTMENT\n  ACCOUNTING_ADJUSTMENT\n  EXPORT\n  PRINT\n  VIEW\n}\n\nmodel AuditLog {\n  id          String      @id @default(cuid())\n  companyId   String\n  branchId    String?\n  userId      String?\n  user        User?       @relation(fields: [userId], references: [id])\n  role        String?\n  action      AuditAction\n  entity      String\n  entityId    String?\n  beforeJson  Json?\n  afterJson   Json?\n  ip          String?\n  userAgent   String?\n  description String?\n  createdAt   DateTime    @default(now())\n\n  @@index([companyId])\n  @@index([userId])\n  @@index([entity, entityId])\n  @@index([action])\n  @@index([createdAt])\n}\n\nmodel Notification {\n  id         String   @id @default(cuid())\n  companyId  String\n  type       String // LOW_STOCK, PO_APPROVAL, TRANSFER_PENDING, TRANSFER_RECEIVED, INVOICE_OVERDUE, etc.\n  title      String\n  message    String?\n  entityType String?\n  entityId   String?\n  branchId   String?\n  priority   String   @default(\"NORMAL\") // LOW, NORMAL, HIGH, URGENT\n  status     String   @default(\"UNREAD\") // UNREAD, READ, ARCHIVED\n  createdAt  DateTime @default(now())\n\n  userNotifications UserNotification[]\n\n  @@index([companyId])\n  @@index([entityType, entityId])\n  @@index([createdAt])\n}\n\nmodel UserNotification {\n  userId         String\n  user           User         @relation(fields: [userId], references: [id], onDelete: Cascade)\n  notificationId String\n  notification   Notification @relation(fields: [notificationId], references: [id], onDelete: Cascade)\n  readAt         DateTime?\n  createdAt      DateTime     @default(now())\n\n  @@id([userId, notificationId])\n  @@index([userId, readAt])\n}\n\nmodel DocumentSequence {\n  id        String   @id @default(cuid())\n  companyId String\n  branchId  String?\n  docType   String // INVOICE, POS, PO, GRN, TRF, PAY, REC, etc.\n  prefix    String\n  separator String   @default(\"-\")\n  year      String?\n  nextSeq   Int      @default(1)\n  padding   Int      @default(6)\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@unique([companyId, branchId, docType, year])\n  @@index([companyId, docType])\n}\n\nmodel Attachment {\n  id           String   @id @default(cuid())\n  companyId    String\n  entityType   String // SUPPLIER, CUSTOMER, PO, INVOICE, EXPENSE, EMPLOYEE, ASSET, PAYMENT, STOCK_ADJUSTMENT\n  entityId     String\n  fileName     String\n  filePath     String\n  mimeType     String\n  size         Int\n  uploadedById String?\n  uploadedAt   DateTime @default(now())\n\n  @@index([entityType, entityId])\n  @@index([companyId])\n}\n\nmodel AppSetting {\n  id        String   @id @default(cuid())\n  companyId String\n  group     String // COMPANY, TAX, CURRENCY, POS, ACCOUNTING, INVENTORY, PROCUREMENT, HR, PAYROLL, NOTIFICATIONS, SYSTEM, APPROVALS\n  key       String\n  value     String\n  dataType  String   @default(\"STRING\") // STRING, NUMBER, BOOLEAN, JSON\n  isPublic  Boolean  @default(false)\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@unique([companyId, group, key])\n  @@index([companyId, group])\n}\n\nmodel ApprovalWorkflow {\n  id         String   @id @default(cuid())\n  companyId  String\n  name       String\n  entityType String // PURCHASE_ORDER, EXPENSE, DISCOUNT, CREDIT_SALE, REFUND, STOCK_ADJUSTMENT, BRANCH_TRANSFER, SUPPLIER_PAYMENT, CUSTOMER_CREDIT_LIMIT, PAYROLL\n  createdAt  DateTime @default(now())\n  updatedAt  DateTime @updatedAt\n\n  levels ApprovalLevel[]\n\n  @@unique([companyId, entityType])\n}\n\nmodel ApprovalLevel {\n  id         String           @id @default(cuid())\n  workflowId String\n  workflow   ApprovalWorkflow @relation(fields: [workflowId], references: [id], onDelete: Cascade)\n  level      Int\n  roleId     String?\n  role       Role?            @relation(fields: [roleId], references: [id])\n  minAmount  Decimal?         @db.Decimal(18, 4)\n  maxAmount  Decimal?         @db.Decimal(18, 4)\n  createdAt  DateTime         @default(now())\n\n  @@index([workflowId])\n}\n\nmodel ApprovalRequest {\n  id            String    @id @default(cuid())\n  companyId     String\n  branchId      String?\n  entityType    String\n  entityId      String\n  entityRef     String?\n  requestedById String?\n  status        String    @default(\"PENDING\") // PENDING, APPROVED, REJECTED, CANCELLED\n  comments      String?\n  currentLevel  Int       @default(1)\n  approvedAt    DateTime?\n  createdAt     DateTime  @default(now())\n  updatedAt     DateTime  @updatedAt\n\n  actions ApprovalAction[]\n\n  @@index([companyId])\n  @@index([entityType, entityId])\n  @@index([status])\n}\n\nmodel ApprovalAction {\n  id                String          @id @default(cuid())\n  approvalRequestId String\n  approvalRequest   ApprovalRequest @relation(fields: [approvalRequestId], references: [id], onDelete: Cascade)\n  level             Int\n  approverId        String?\n  action            String // APPROVE, REJECT\n  comments          String?\n  actionAt          DateTime        @default(now())\n\n  @@index([approvalRequestId])\n}\n"
}

